let username = msg.payload.wasos_username;
let password = msg.payload.wasos_password;

// Encode to Base64 for Basic Auth
let auth = Buffer.from(username + ":" + password).toString('base64');

msg.headers = {
    'Authorization': 'Basic ' + auth
};

msg.url = global.get("wasos_url") + "/apisec/login";

// store variables to persist after request
msg.config = {
    username: username,
    chatroom_name: msg.payload.wasos_chatroom_name
}

return msg;
